export const DICT = { en, fr, es, pt, de, ja, ko };
let lang = 'en';
export function detectLang() {
  try { const s = localStorage.getItem('ahq_lang'); if (s && DICT[s]) return s; } catch (e) {}
  const n = (navigator.language || 'en').slice(0, 2).toLowerCase();
  return DICT[n] ? n : 'en';
}
export function setLang(l) { lang = DICT[l] ? l : 'en'; try { localStorage.setItem('ahq_lang', lang); } catch (e) {} document.documentElement.lang = lang === 'pt' ? 'pt-BR' : lang; document.documentElement.dataset.lang = lang; }
export function getLang() { return lang; }
export const TV = {};
export function t(key, vars) {
  vars = vars ? Object.assign({}, TV, vars) : TV;
  let s = null; if (vars && vars.g) s = DICT[lang][key + '.' + vars.g];
  if (s == null) s = DICT[lang][key]; if (s == null) s = en[key]; if (s == null) return key;
  if (typeof s === 'string' && s.indexOf('{') >= 0) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] != null ? vars[k] : m));
  return s;
}
export function tList(key) { const v = DICT[lang][key] || en[key]; return Array.isArray(v) ? v : [v]; }
